          '--output', path.dirname(distPath),
          '--config', configPath
        ], {
          stdio: 'inherit',
          windowsHide: true
        });

        if (result.status !== 0) {
          throw new Error(`混淆失败: ${relPath}`);
        }

        // 处理自动生成的 -obfuscated 后缀
