        if (fs.existsSync(obfuscatedFile)) {
          fs.renameSync(obfuscatedFile, distPath);
        }
      } else {
        console.log(chalk.green(`复制: ${relPath}`));
        fs.copyFileSync(srcFullPath, distPath);
      }
    }
  });
}
